#1. reads the baseline training summaries from data/reference.csv 
#2. compares against inference logs from data/current_logs.jsonl generated by app/load_test.py
#3. runs KS-Test, PSI and Chi-Square tests
import os
import json
import numpy as np
import pandas as pd
from scipy.stats import ks_2samp, chi2_contingency
from tabulate import tabulate

LOG_FILE = "data/current_logs.jsonl"

def calculate_psi(reference, current, num_bins=10):
    """Calculates Population Stability Index (PSI) between two continuous distributions."""
    ref_counts, bin_edges = np.histogram(reference, bins=num_bins)
    curr_counts, _ = np.histogram(current, bins=bin_edges)
    
    ref_pct = np.where(ref_counts == 0, 0.0001, ref_counts) / len(reference)
    curr_pct = np.where(curr_counts == 0, 0.0001, curr_counts) / len(current)
    
    psi_value = np.sum((curr_pct - ref_pct) * np.log(curr_pct / ref_pct))
    return float(psi_value)

def analyze_drift():
    if not os.path.exists(LOG_FILE):
        print(f"Error: {LOG_FILE} not found! Run 'python app/load_test.py' first.")
        return

    # Load logged records
    records = []
    with open(LOG_FILE, "r") as f:
        for line in f:
            records.append(json.loads(line))
            
    df = pd.DataFrame(records)
    
    if "window" not in df.columns:
        print("Error: Missing 'window' field in log data. Re-run app/load_test.py.")
        return

    ref_df = df[df["window"] == "reference"]
    curr_df = df[df["window"] == "current"]

    print(f"\n--- Data Drift Analysis Summary ---")
    print(f"Reference Window Samples: {len(ref_df)}")
    print(f"Current Window Samples:   {len(curr_df)}\n")

    results = []

    # 1. KS-Test on Text Length (Numerical)
    ks_stat, ks_pvalue = ks_2samp(ref_df["text_length"], curr_df["text_length"])
    results.append([
        "text_length",
        "KS-Test",
        f"Stat: {ks_stat:.4f}, p: {ks_pvalue:.4e}",
        "DRIFT DETECTED" if ks_pvalue < 0.05 else "NO DRIFT",
        "Significant shift in input text length distribution." if ks_pvalue < 0.05 else "Length distribution unchanged."
    ])

    # 2. PSI on Model Prediction Confidence (Numerical continuous)
    psi_val = calculate_psi(ref_df["confidence"], curr_df["confidence"])
    results.append([
        "confidence",
        "PSI",
        f"PSI Score: {psi_val:.4f}",
        "DRIFT DETECTED" if psi_val > 0.25 else ("MODERATE SHIFT" if psi_val > 0.1 else "NO DRIFT"),
        "Significant distribution shift (PSI > 0.25)." if psi_val > 0.25 else "Stable confidence metrics."
    ])

    # 3. Chi-Square Test on Sentiment Predictions (Categorical)
    ref_preds = ref_df["prediction"].value_counts().reindex([0, 1], fill_value=0)
    curr_preds = curr_df["prediction"].value_counts().reindex([0, 1], fill_value=0)
    contingency_table = [ref_preds.values, curr_preds.values]
    
    chi2_stat, chi2_pvalue, _, _ = chi2_contingency(contingency_table)
    results.append([
        "prediction",
        "Chi-Square",
        f"Stat: {chi2_stat:.4f}, p: {chi2_pvalue:.4e}",
        "DRIFT DETECTED" if chi2_pvalue < 0.05 else "NO DRIFT",
        "Significant change in output sentiment distribution." if chi2_pvalue < 0.05 else "Prediction outputs stable."
    ])

    headers = ["Feature", "Test Used", "Metric / Score", "Drift Status", "Interpretation"]
    print(tabulate(results, headers=headers, tablefmt="fancy_grid"))

if __name__ == "__main__":
    analyze_drift()